typedef struct Token {
    TokType tag;
    orbit_string text;
    orbit_int line;
    orbit_int col;
} Token;
#define Token(...) (Token*)orbit_model_Token_create(arena, __VA_ARGS__)
static inline Token* orbit_model_Token_create(OrbitArena* arena_, TokType tag, orbit_string text, orbit_int line, orbit_int col) {
    Token* m = (Token*)orbit_alloc(arena_, sizeof(Token));
    m->tag = tag;
    m->text = text;
    m->line = line;
    m->col = col;
    return m;
}

